        (Ok(Some((a, x))), Ok(Some((b, y)))) => {
            assert_eq!(a,b);assert_eq!(x.len(),y.len());
            for ((la,sa),(lb,sb)) in x.iter().zip(y) {
                assert_eq!(la,lb);assert_eq!(sa.as_ref().as_slice(),sb.as_ref().as_slice());
